{"explanation":"Start with a square of area 1. Fill half of it, then half of the remaining space, then half again—adding areas 1/2, 1/4, 1/8, and so on. After n steps, only 1/2ⁿ remains unfilled; because this tends to zero, the infinite sum fills the whole square and equals 1.","manimCode":"const title = new Text({ text: 'Half of what remains', fontSize: 32, color: WHITE });
title.moveTo([0, 3.1, 0]);
const outline = new Square({ sideLength: 3, color: WHITE });
outline.moveTo([-2, 0, 0]);
outline.setFillOpacity(0);
outline.setStrokeWidth(3);

const equation = new MathTex({ latex: '\\frac12 + \\frac14 + \\frac18 + \\cdots = 1', color: WHITE });
await equation.waitForRender();
equation.scale(0.8);
equation.moveTo([2.3, 1.3, 0]);

const caption = new Text({ text: 'Each step halves the empty space.', fontSize: 20, color: GRAY });
caption.moveTo([-2, -2.2, 0]);

const tiles = [];
const tileLabels = [];
const remainingBoxes = [[-3.5, -1.5, -0.5, 1.5]];
const palette = [BLUE, TEAL, GREEN, BLUE_C, TEAL, GREEN_C];
let leftEdge = -3.5;
let bottomEdge = -1.5;
let rightEdge = -0.5;
let topEdge = 1.5;

for (let i = 0; i < 12; i++) {
  let bounds;
  if (i % 2 === 0) {
    const middle = (leftEdge + rightEdge) / 2;
    bounds = [leftEdge, bottomEdge, middle, topEdge];
    leftEdge = middle;
  } else {
    const middle = (bottomEdge + topEdge) / 2;
    bounds = [leftEdge, bottomEdge, rightEdge, middle];
    bottomEdge = middle;
  }
  const [a, b, c, d] = bounds;
  const tile = new Polygon({ vertices: [[a,b,0],[c,b,0],[c,d,0],[a,d,0]], color: palette[i % palette.length] });
  tile.setFill(palette[i % palette.length], 0.85);
  tile.setStrokeWidth(1);
  tiles.push(tile);
  remainingBoxes.push([leftEdge, bottomEdge, rightEdge, topEdge]);
  if (i < 4) {
    const fraction = new MathTex({ latex: '\\frac{1}{' + Math.pow(2, i + 1) + '}', color: WHITE });
    await fraction.waitForRender();
    fraction.scale([0.75, 0.65, 0.5, 0.4][i]);
    fraction.moveTo([(a+c)/2, (b+d)/2, 0]);
    tileLabels.push(fraction);
  }
}

const emptyOutline = new Polygon({ vertices: [[-3.5,-1.5,0],[-0.5,-1.5,0],[-0.5,1.5,0],[-3.5,1.5,0]], color: YELLOW });
emptyOutline.setFillOpacity(0);
emptyOutline.setStrokeWidth(2);
let filledLabel;
let emptyLabel;
function updateReadout(n) {
  if (filledLabel) scene.remove(filledLabel);
  if (emptyLabel) scene.remove(emptyLabel);
  const denominator = Math.pow(2, n);
  filledLabel = new Text({ text: n === 0 ? 'Filled area: 0' : 'Filled area: ' + (denominator - 1) + '/' + denominator, fontSize: 25, color: TEAL });
  filledLabel.moveTo([2.3, 0.25, 0]);
  emptyLabel = new Text({ text: n === 0 ? 'Unfilled area: 1' : 'Unfilled area: 1/' + denominator, fontSize: 25, color: YELLOW });
  emptyLabel.moveTo([2.3, -0.45, 0]);
  scene.add(filledLabel, emptyLabel);
  const [a,b,c,d] = remainingBoxes[n];
  emptyOutline.setVertices([[a,b,0],[c,b,0],[c,d,0],[a,d,0]]);
}

await scene.play(new AnimationGroup([new Write(title), new Create(outline), new Write(equation)]));
scene.add(caption, emptyOutline);
updateReadout(0);
await scene.wait(0.6);
for (let n = 1; n <= 6; n++) {
  await scene.play(new FadeIn(tiles[n - 1]));
  if (n <= tileLabels.length) scene.add(tileLabels[n - 1]);
  updateReadout(n);
  await scene.wait(0.45);
}

const limitNote = new Text({ text: 'The leftover area tends to zero.', fontSize: 21, color: WHITE });
limitNote.moveTo([2.3, -1.2, 0]);
await scene.play(new FadeIn(limitNote));

function showSteps(n) {
  for (const tile of tiles) scene.remove(tile);
  for (const label of tileLabels) scene.remove(label);
  scene.remove(emptyOutline);
  for (let i = 0; i < n; i++) {
    scene.add(tiles[i]);
    if (i < tileLabels.length) scene.add(tileLabels[i]);
  }
  updateReadout(n);
  scene.add(emptyOutline);
}
const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({ label: 'Number of filled pieces', min: 0, max: 12, step: 1, value: 6, onChange: (value) => showSteps(Math.round(value)) });
await scene.wait(999999);"}

